sys_script_client.script:
// Client Script: onChange
// Table: Student Profile (x_1983287_studen_0_student_profile)
// Field: department

function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    // Get the display value of the selected Department
    var dept = g_form.getReference('department', function(deptRecord) {
        if (deptRecord && deptRecord.hod) {
            // Auto-populate HOD field with department's HOD reference
            g_form.setValue('hod', deptRecord.hod);
        } else {
            g_form.clearValue('hod'); // Clear if no HOD found
        }
    });
}
